<script lang="ts">
	type CapColor = 'orange' | 'dark' | 'light';
	type Cap = { x: number; y: number; w: number; label: string; color: CapColor };

	let { class: class_name = '' }: { class?: string } = $props();

	const U = 74;
	const STEP = U + 5;
	const ROW_A = 33;
	const ROW_B = 138;
	const ROW_C = 240;

	const INK: Record<CapColor, string> = { orange: '#3b2414', dark: '#f2f2f2', light: '#2b2b2b' };
	const LIP: Record<CapColor, string> = { orange: '#a85d1d', dark: '#202124', light: '#848484' };

	const caps: Cap[] = [
		...(
			[
				['1', 'orange'],
				['2', 'dark'],
				['3', 'dark'],
				['4', 'dark'],
				['5', 'light'],
				['6', 'light']
			] as const
		).map(([label, color], i) => ({ x: 148 + i * STEP, y: ROW_A, w: U, label, color })),
		...(
			[
				['7', 'dark'],
				['8', 'dark'],
				['9', 'light'],
				['0', 'light'],
				['•', 'light']
			] as const
		).map(([label, color], i) => ({ x: 36 + i * STEP, y: ROW_B, w: U, label, color })),
		{ x: 431, y: ROW_B, w: 186, label: 'ENTER', color: 'orange' },
		{ x: 36, y: ROW_C, w: 113.5, label: '−', color: 'orange' },
		{ x: 154.5, y: ROW_C, w: U, label: '+', color: 'dark' },
		{ x: 233.5, y: ROW_C, w: 274.5, label: '', color: 'dark' }
	];
</script>

